def payoff(principal, apr, monthly_sales, share, months=60):
    bal, paid_int = principal, 0
    for m in range(1, months + 1):
        interest = bal * apr / 12
        pay = min(monthly_sales[m - 1] * share, bal + interest)
        paid_int += interest
        bal = bal + interest - pay
        if bal <= 0.5:
            return m, round(paid_int)
    return None, round(bal)

flat = [8_000_000] * 60                       # 월 매출 800만원 그대로
drop = [8_000_000] * 3 + [4_000_000] * 57    # 넉 달째부터 400만원
for name, s in [("매출 그대로", flat), ("매출 반토막", drop)]:
    m, i = payoff(10_000_000, 0.141, s, 0.10)
    print(f"{name}: {m}개월에 다 갚음, 낸 이자 {i:,}원")

import math, random
random.seed(7)
def run(n, p):
    return sum(random.random() < p for _ in range(n))

def z(b1, n1, b2, n2):
    p = (b1 + b2) / (n1 + n2)
    se = math.sqrt(p * (1 - p) * (1 / n1 + 1 / n2))
    return (b2 / n2 - b1 / n1) / se

for total in (2_000, 20_000):
    n1, n2 = int(total * 0.9), int(total * 0.1)
    b1, b2 = run(n1, 0.040), run(n2, 0.050)   # 실제 차이는 1%p
    print(f"{total:,}건: 챔피언 {b1/n1:.1%} · 챌린저 {b2/n2:.1%} · z={z(b1,n1,b2,n2):.2f}")
